SELECT id, accountNumber, password, balance, memberId, created_at, updated_at
FROM account
WHERE memberId = #{memberId}

SELECT id, accountNumber, password, balance, memberId, created_at, updated_at
FROM account
WHERE id = #{id}

SELECT id, accountNumber, password, balance, memberId, created_at, updated_at
FROM account
WHERE accountNumber = #{accountNumber}

SELECT count(*)
FROM account
WHERE accountNumber = #{accountNumber}
